### Mini‑script (JavaScript/Node) you can try right now

```js
// npm i esprima
const esprima = require('esprima');
const fs = require('fs');
const source = fs.readFileSync('yourFile.js', 'utf8');

const CONTROL = new Set(['if','else','switch','case','for','while','do','return','throw','await','yield','break','continue']);
const LOGICAL = new Set(['&&','||','!']);
const ARITH   = new Set(['+','-','*','/','%','<','>','<=','>=','===','!==','==','!=']);
const TERNARY = new Set(['?']);
const NULLCO  = new Set(['??']);

function tokenWeight(tok) {
  if (CONTROL.has(tok.value)) return 3;
  if (TERNARY.has(tok.value)) return 3;
  if (LOGICAL.has(tok.value)) return 2;
  if (ARITH.has(tok.value))   return 1.5;
  if (tok.type === 'Identifier') {
    // naive “obscure name” check
    return tok.value.length <= 1 ? 2 : 1;
  }
  if (tok.type === 'Numeric' || tok.type === 'String' || tok.type === 'RegularExpression') {
    return tok.value.length > 30 ? 2 : 1;
  }
  if (tok.type === 'Punctuator' && (tok.value === '(' || tok.value === '[')) {
    // function or property access start – look ahead
    return 0.5;
  }
  if (tok.type === 'Punctuator') return 0.5;
  return 0;
}

// Tokenise and score per line
const tokens = esprima.tokenize(source, { loc: true });
const lineScores = {};

tokens.forEach(tok => {
  const line = tok.loc.start.line;
  lineScores[line] = (lineScores[line] || 0) + tokenWeight(tok);
});

Object.entries(lineScores)
  .sort((a,b)=>a[0]-b[0])
  .forEach(([ln, sc]) => console.log(`Line ${ln}: ${sc.toFixed(1)}`));
```

